      final r = _followRef(schema[r'$ref'] as String, r'$ref', inst, ctx, errors);
      if (!r.ok) ok = false;
      out.merge(r);
      // Up to draft-07, `$ref` is the whole schema.
      if (!d.atLeast2019) return ok ? out : _Annotations.invalid();
    }
    if (d == JsonSchemaDialect.draft2020 && schema[r'$dynamicRef'] is String) {
      final r = _followDynamicRef(schema[r'$dynamicRef'] as String, inst, ctx, errors);
      if (!r.ok) ok = false;
      out.merge(r);
