    if (d == JsonSchemaDialect.draft2019 && schema[r'$recursiveRef'] is String) {
      final r = _followRecursiveRef(schema[r'$recursiveRef'] as String, inst, ctx, errors);
      if (!r.ok) ok = false;
      out.merge(r);
