          final r = _eval(schema['then'], inst, ctx.at('then'), errors);
          if (!r.ok) ok = false;
          out.merge(r);
        }
      } else if (schema.containsKey('else')) {
        final r = _eval(schema['else'], inst, ctx.at('else'), errors);
        if (!r.ok) ok = false;
        out.merge(r);
      }
