    if (inst is Map) {
      if (!_object(schema, inst, ctx, errors, out, fail)) ok = false;
    }
    if (inst is List) {
      if (!_array(schema, inst, ctx, errors, out, fail)) ok = false;
    }

    // Unevaluated keywords see everything the rest of this schema evaluated.
