      if (inst is List && schema.containsKey('unevaluatedItems')) {
        for (var i = 0; i < inst.length; i++) {
          if (out.allItems || out.items.contains(i)) continue;
          final r = _eval(schema['unevaluatedItems'], inst[i],
              ctx.at('unevaluatedItems').item('$i'), errors);
          if (!r.ok) ok = false;
        }
        out.allItems = true;
      }
    }

    if (!ok) {
      if (errors != null && errors.length == before) {
        errors.add(JsonSchemaError(ctx.ipath, ctx.kpath, 'does not match the schema'));
      }
      return _Annotations.invalid();
    }
    return out;
  }

  _Annotations _followRef(String ref, String keyword, Object? inst, _Ctx c, List<JsonSchemaError>? errors) {
    final target = _lookup(_resolve(c.base, ref));
    if (target == null) throw JsonSchemaException('unresolvable $keyword "$ref"');
    return _eval(target.node, inst, c.into(keyword, target.base), errors);
  }

  _Annotations _followDynamicRef(String ref, Object? inst, _Ctx c, List<JsonSchemaError>? errors) {
    final uri = _resolve(c.base, ref);
    var target = _lookup(uri);
    if (target == null) throw JsonSchemaException(r'unresolvable $dynamicRef "' '$ref"');
    final name = uri.hasFragment ? uri.fragment : '';
    final initialIsDynamic = name.isNotEmpty &&
        !name.startsWith('/') &&
        _dynamicAnchors.contains('${_withoutFragment(uri)}#$name');
    if (initialIsDynamic) {
      // The outermost resource in the dynamic scope with that dynamic anchor.
      for (final scope in c.dynamicScope) {
        final key = '$scope#$name';
        if (_dynamicAnchors.contains(key)) {
          target = _anchors[key];
          break;
        }
      }
    }
    return _eval(target!.node, inst, c.into(r'$dynamicRef', target.base), errors);
  }

  _Annotations _followRecursiveRef(String ref, Object? inst, _Ctx c, List<JsonSchemaError>? errors) {
    var target = _lookup(_resolve(c.base, ref));
    if (target == null) throw JsonSchemaException(r'unresolvable $recursiveRef "' '$ref"');
    if (target.node is Map && (target.node as Map)[r'$recursiveAnchor'] == true) {
      for (final scope in c.dynamicScope) {
        if (_recursiveAnchors.contains(scope.toString())) {
          target = _resources[scope.toString()];
          break;
        }
      }
    }
    return _eval(target!.node, inst, c.into(r'$recursiveRef', target.base), errors);
  }

  // -------------------------------------------------------------------------
  // Assertions (validation vocabulary)
  // -------------------------------------------------------------------------

  void _assertions(Map schema, Object? inst, _Ctx c, void Function(String, String) fail) {
    final d = _dialect;
    final type = schema['type'];
    if (type != null) {
      final types = type is List ? type : [type];
      if (!types.any((t) => _isType(inst, t, d))) {
        fail('type', 'expected ${types.join(' or ')}, got ${_typeName(inst)}');
      }
    }
    final enumValues = schema['enum'];
    if (enumValues is List && !enumValues.any((v) => _jsonEquals(v, inst))) {
      fail('enum', 'not one of the allowed values');
    }
    if (d.index >= JsonSchemaDialect.draft6.index && schema.containsKey('const') && !_jsonEquals(schema['const'], inst)) {
      fail('const', 'not the required value');
    }

    if (inst is num) {
      final multipleOf = schema['multipleOf'];
      if (multipleOf is num && !_isMultiple(inst, multipleOf)) {
        fail('multipleOf', 'not a multiple of $multipleOf');
      }
      final maximum = schema['maximum'];
      final minimum = schema['minimum'];
      if (d == JsonSchemaDialect.draft4) {
        if (maximum is num) {
          final exclusive = schema['exclusiveMaximum'] == true;
          if (exclusive ? inst >= maximum : inst > maximum) fail('maximum', 'greater than ${exclusive ? 'or equal to ' : ''}$maximum');
        }
        if (minimum is num) {
          final exclusive = schema['exclusiveMinimum'] == true;
          if (exclusive ? inst <= minimum : inst < minimum) fail('minimum', 'less than ${exclusive ? 'or equal to ' : ''}$minimum');
        }
      } else {
        if (maximum is num && inst > maximum) fail('maximum', 'greater than $maximum');
        if (minimum is num && inst < minimum) fail('minimum', 'less than $minimum');
        final exMax = schema['exclusiveMaximum'];
        if (exMax is num && inst >= exMax) fail('exclusiveMaximum', 'not less than $exMax');
        final exMin = schema['exclusiveMinimum'];
        if (exMin is num && inst <= exMin) fail('exclusiveMinimum', 'not greater than $exMin');
      }
    }

    if (inst is String) {
      final length = inst.runes.length;
      final maxLength = schema['maxLength'];
      if (maxLength is num && length > maxLength) fail('maxLength', 'longer than $maxLength characters');
      final minLength = schema['minLength'];
      if (minLength is num && length < minLength) fail('minLength', 'shorter than $minLength characters');
      final pattern = schema['pattern'];
      if (pattern is String && !_regex(pattern).hasMatch(inst)) {
        fail('pattern', 'does not match /$pattern/');
      }
    }

    if (inst is List) {
      final maxItems = schema['maxItems'];
      if (maxItems is num && inst.length > maxItems) fail('maxItems', 'more than $maxItems items');
      final minItems = schema['minItems'];
      if (minItems is num && inst.length < minItems) fail('minItems', 'fewer than $minItems items');
      if (schema['uniqueItems'] == true) {
        outer:
        for (var i = 0; i < inst.length; i++) {
          for (var j = i + 1; j < inst.length; j++) {
            if (_jsonEquals(inst[i], inst[j])) {
              fail('uniqueItems', 'items $i and $j are equal');
              break outer;
            }
          }
        }
      }
    }

    if (inst is Map) {
      final maxProperties = schema['maxProperties'];
      if (maxProperties is num && inst.length > maxProperties) fail('maxProperties', 'more than $maxProperties properties');
      final minProperties = schema['minProperties'];
      if (minProperties is num && inst.length < minProperties) fail('minProperties', 'fewer than $minProperties properties');
      final required = schema['required'];
      if (required is List) {
        final missing = required.where((k) => !inst.containsKey(k)).toList();
        if (missing.isNotEmpty) fail('required', 'missing required ${missing.map((k) => '"$k"').join(', ')}');
      }
      final dependentRequired = d.atLeast2019 ? schema['dependentRequired'] : null;
      if (dependentRequired is Map) {
        for (final e in dependentRequired.entries) {
          if (!inst.containsKey(e.key) || e.value is! List) continue;
          final missing = (e.value as List).where((k) => !inst.containsKey(k)).toList();
          if (missing.isNotEmpty) fail('dependentRequired', '"${e.key}" requires ${missing.map((k) => '"$k"').join(', ')}');
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // Object and array applicators
  // -------------------------------------------------------------------------

  bool _object(Map schema, Map inst, _Ctx c, List<JsonSchemaError>? errors, _Annotations out,
      void Function(String, String) fail) {
    final d = _dialect;
    var ok = true;
    final properties = schema['properties'];
    final patternProperties = schema['patternProperties'];
    final matched = <String>{};
    if (properties is Map) {
      for (final e in properties.entries) {
        final k = '${e.key}';
        if (!inst.containsKey(k)) continue;
        matched.add(k);
        final r = _eval(e.value, inst[k], c.at('properties/${_escape(k)}').item(k), errors);
        if (!r.ok) ok = false;
        out.props.add(k);
      }
    }
    if (patternProperties is Map) {
      for (final e in patternProperties.entries) {
        final re = _regex('${e.key}');
        for (final key in inst.keys) {
          final k = '$key';
          if (!re.hasMatch(k)) continue;
          matched.add(k);
          final r = _eval(e.value, inst[key], c.at('patternProperties/${_escape('${e.key}')}').item(k), errors);
          if (!r.ok) ok = false;
          out.props.add(k);
        }
      }
    }
    if (schema.containsKey('additionalProperties')) {
      for (final key in inst.keys) {
        final k = '$key';
        if (matched.contains(k)) continue;
        final r = _eval(schema['additionalProperties'], inst[key], c.at('additionalProperties').item(k), errors);
        if (!r.ok) ok = false;
        out.props.add(k);
      }
    }
    if (d.index >= JsonSchemaDialect.draft6.index && schema.containsKey('propertyNames')) {
      for (final key in inst.keys) {
        final r = _eval(schema['propertyNames'], '$key', c.at('propertyNames').item('$key'), errors);
        if (!r.ok) ok = false;
      }
    }
    final dependentSchemas = d.atLeast2019 ? schema['dependentSchemas'] : null;
    if (dependentSchemas is Map) {
      for (final e in dependentSchemas.entries) {
        if (!inst.containsKey(e.key)) continue;
        final r = _eval(e.value, inst, c.at('dependentSchemas/${_escape('${e.key}')}'), errors);
        if (!r.ok) ok = false;
        out.merge(r);
      }
    }
    final dependencies = d.atLeast2019 ? null : schema['dependencies'];
    if (dependencies is Map) {
      for (final e in dependencies.entries) {
        if (!inst.containsKey(e.key)) continue;
        if (e.value is List) {
          final missing = (e.value as List).where((k) => !inst.containsKey(k)).toList();
          if (missing.isNotEmpty) fail('dependencies', '"${e.key}" requires ${missing.map((k) => '"$k"').join(', ')}');
        } else {
          final r = _eval(e.value, inst, c.at('dependencies/${_escape('${e.key}')}'), errors);
          if (!r.ok) ok = false;
        }
      }
    }
    return ok;
  }

  bool _array(Map schema, List inst, _Ctx c, List<JsonSchemaError>? errors, _Annotations out,
      void Function(String, String) fail) {
    final d = _dialect;
    var ok = true;
    if (d == JsonSchemaDialect.draft2020) {
      final prefix = schema['prefixItems'];
      var start = 0;
      if (prefix is List) {
        for (var i = 0; i < prefix.length && i < inst.length; i++) {
          final r = _eval(prefix[i], inst[i], c.at('prefixItems/$i').item('$i'), errors);
          if (!r.ok) ok = false;
          out.items.add(i);
        }
        start = prefix.length;
      }
      if (schema.containsKey('items')) {
        for (var i = start; i < inst.length; i++) {
          final r = _eval(schema['items'], inst[i], c.at('items').item('$i'), errors);
          if (!r.ok) ok = false;
        }
        out.allItems = true;
      }
    } else {
      final items = schema['items'];
      if (items is List) {
        for (var i = 0; i < items.length && i < inst.length; i++) {
          final r = _eval(items[i], inst[i], c.at('items/$i').item('$i'), errors);
          if (!r.ok) ok = false;
          out.items.add(i);
        }
        if (schema.containsKey('additionalItems')) {
          for (var i = items.length; i < inst.length; i++) {
            final r = _eval(schema['additionalItems'], inst[i], c.at('additionalItems').item('$i'), errors);
            if (!r.ok) ok = false;
          }
          out.allItems = true;
        }
      } else if (schema.containsKey('items')) {
        for (var i = 0; i < inst.length; i++) {
          final r = _eval(items, inst[i], c.at('items').item('$i'), errors);
          if (!r.ok) ok = false;
        }
        out.allItems = true;
      }
    }
    if (d.index >= JsonSchemaDialect.draft6.index && schema.containsKey('contains')) {
      var count = 0;
      for (var i = 0; i < inst.length; i++) {
        final r = _eval(schema['contains'], inst[i], c.at('contains').item('$i'), null);
        if (r.ok) {
          count++;
          if (d == JsonSchemaDialect.draft2020) out.items.add(i);
        }
      }
      final minContains = d.atLeast2019 ? schema['minContains'] : null;
      final maxContains = d.atLeast2019 ? schema['maxContains'] : null;
      final min = minContains is num ? minContains : 1;
      if (count < min) {
        fail('contains', count == 0 && min == 1 ? 'no item matches "contains"' : 'only $count items match "contains", at least $min required');
      }
      if (maxContains is num && count > maxContains) {
        fail('maxContains', '$count items match "contains", at most $maxContains allowed');
      }
    }
    return ok;
  }

  // -------------------------------------------------------------------------
  // Values
  // -------------------------------------------------------------------------

  static bool _isType(Object? v, Object? type, JsonSchemaDialect d) {
    switch (type) {
      case 'null':
        return v == null;
      case 'boolean':
        return v is bool;
      case 'object':
        return v is Map;
      case 'array':
        return v is List;
      case 'string':
        return v is String;
      case 'number':
        return v is num;
      case 'integer':
        if (v is int) return true;
        if (v is double && d != JsonSchemaDialect.draft4) {
          return v.isFinite && v == v.truncateToDouble();
        }
        return false;
    }
    return false;
  }

  static String _typeName(Object? v) => switch (v) {
        null => 'null',
        bool() => 'boolean',
        Map() => 'object',
        List() => 'array',
        String() => 'string',
        int() => 'integer',
        num() => 'number',
        _ => '${v.runtimeType}',
      };

  static bool _jsonEquals(Object? a, Object? b) {
    if (a is num && b is num) return a == b;
    if (a is List && b is List) {
      if (a.length != b.length) return false;
      for (var i = 0; i < a.length; i++) {
        if (!_jsonEquals(a[i], b[i])) return false;
      }
      return true;
    }
    if (a is Map && b is Map) {
      if (a.length != b.length) return false;
      for (final k in a.keys) {
        if (!b.containsKey(k) || !_jsonEquals(a[k], b[k])) return false;
      }
      return true;
    }
    if (a is bool || b is bool) return a == b && a.runtimeType == b.runtimeType;
    return a == b;
  }

  /// Exact for decimal literals: both sides become integers over a common
  /// power of ten.
  static bool _isMultiple(num value, num divisor) {
    if (divisor <= 0) return true;
    if (value is int && divisor is int) return value % divisor == 0;
    final a = _decimal(value);
    final b = _decimal(divisor);
    if (a == null || b == null) return false;
    final scale = a.$2 > b.$2 ? a.$2 : b.$2;
    final x = a.$1 * BigInt.from(10).pow(scale - a.$2);
    final y = b.$1 * BigInt.from(10).pow(scale - b.$2);
    return y != BigInt.zero && x.remainder(y) == BigInt.zero;
  }

  /// [n] as (digits, decimals): 1.25 -> (125, 2).
  static (BigInt, int)? _decimal(num n) {
    if (n is double && !n.isFinite) return null;
    var s = n is int ? '$n' : (n as double).toString();
    var exponent = 0;
    final e = s.indexOf(RegExp('[eE]'));
    if (e >= 0) {
      exponent = int.parse(s.substring(e + 1));
      s = s.substring(0, e);
    }
    var decimals = 0;
    final dot = s.indexOf('.');
    if (dot >= 0) {
      decimals = s.length - dot - 1;
      s = s.substring(0, dot) + s.substring(dot + 1);
    }
    var digits = BigInt.parse(s);
    decimals -= exponent;
    if (decimals < 0) {
      digits *= BigInt.from(10).pow(-decimals);
      decimals = 0;
    }
    return (digits, decimals);
  }

  final Map<String, RegExp> _regexCache = {};

  RegExp _regex(String pattern) => _regexCache.putIfAbsent(pattern, () {
        try {
          return RegExp(pattern, unicode: true);
        } on FormatException {
          throw JsonSchemaException('invalid regular expression: $pattern');
        }
      });

  static String? _formatProblem(String format, String value) {
    switch (format) {
      case 'email':
        return _isEmail(value) ? null : 'not an email address (RFC 5321)';
      case 'uri':
        return _isUri(value) ? null : 'not an absolute URI (RFC 3986)';
      case 'date':
        return _isDate(value) ? null : 'not a full-date (RFC 3339)';
      case 'date-time':
        return _isDateTime(value) ? null : 'not a date-time (RFC 3339)';
    }
    return null;
  }

  static final _dateRe = RegExp(r'^([0-9]{4})-([0-9]{2})-([0-9]{2})$');

  static bool _isDate(String value) {
    final m = _dateRe.firstMatch(value);
    if (m == null) return false;
    final y = int.parse(m[1]!), mo = int.parse(m[2]!), d = int.parse(m[3]!);
    if (mo < 1 || mo > 12 || d < 1) return false;
    final leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    const days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    return d <= (mo == 2 && leap ? 29 : days[mo - 1]);
  }

  static final _dateTimeRe = RegExp(
      r'^([0-9]{4}-[0-9]{2}-[0-9]{2})[Tt]([0-9]{2}):([0-9]{2}):([0-9]{2})(\.[0-9]+)?'
      r'([Zz]|([+-])([0-9]{2}):([0-9]{2}))$');

  static bool _isDateTime(String value) {
    final m = _dateTimeRe.firstMatch(value);
    if (m == null || !_isDate(m[1]!)) return false;
    final h = int.parse(m[2]!), mi = int.parse(m[3]!), sec = int.parse(m[4]!);
    if (h > 23 || mi > 59 || sec > 60) return false;
    var offset = 0;
    if (m[7] != null) {
      final oh = int.parse(m[8]!), om = int.parse(m[9]!);
      if (oh > 23 || om > 59) return false;
      offset = (m[7] == '-' ? -1 : 1) * (oh * 60 + om);
    }
    // A leap second is the last second of a UTC day.
    if (sec == 60) {
      final utcMinute = ((h * 60 + mi - offset) % 1440 + 1440) % 1440;
      if (utcMinute != 23 * 60 + 59) return false;
    }
    return true;
  }

  static final _atext = RegExp(r"^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+$");
  static final _label = RegExp(r'^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$');

  /// RFC 5321 Mailbox: Dot-string or Quoted-string, `@`, a domain or an
  /// address literal. ASCII only.
  static bool _isEmail(String value) {
    String local;
    int at;
    if (value.startsWith('"')) {
      var i = 1;
      for (; i < value.length; i++) {
        final c = value.codeUnitAt(i);
        if (c == 0x5c) {
          if (++i >= value.length) return false;
          final q = value.codeUnitAt(i);
          if (q < 32 || q > 126) return false;
        } else if (c == 0x22) {
          break;
        } else if (c < 32 || c > 126) {
          return false;
        }
      }
      if (i >= value.length) return false;
      at = i + 1;
      if (at >= value.length || value[at] != '@') return false;
      local = value.substring(0, at);
    } else {
      at = value.indexOf('@');
      if (at <= 0) return false;
      local = value.substring(0, at);
      if (!local.split('.').every(_atext.hasMatch)) return false;
    }
    final domain = value.substring(at + 1);
    if (local.isEmpty || domain.isEmpty) return false;
    if (domain.startsWith('[')) {
      if (!domain.endsWith(']')) return false;
      final literal = domain.substring(1, domain.length - 1);
      if (literal.toLowerCase().startsWith('ipv6:')) return _isIPv6(literal.substring(5));
      return _isIPv4(literal);
    }
    return domain.split('.').every(_label.hasMatch);
  }

  static final _ipv4Re = RegExp(r'^(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])(\.(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])){3}$');

  static bool _isIPv4(String s) => _ipv4Re.hasMatch(s);

  static final _hex16 = RegExp(r'^[0-9A-Fa-f]{1,4}$');

  static bool _isIPv6(String s) {
    if (s.isEmpty) return false;
    var groups = 8;
    var text = s;
    final lastColon = text.lastIndexOf(':');
    if (lastColon >= 0 && text.substring(lastColon + 1).contains('.')) {
      if (!_isIPv4(text.substring(lastColon + 1))) return false;
      groups = 6;
      text = text.substring(0, lastColon + 1);
      if (text.endsWith(':') && !text.endsWith('::')) text = text.substring(0, text.length - 1);
    }
    final halves = text.split('::');
    if (halves.length > 2) return false;
    List<String> parts(String h) => h.isEmpty ? const [] : h.split(':');
    final head = parts(halves[0]);
    final tail = halves.length == 2 ? parts(halves[1]) : const <String>[];
    if (![...head, ...tail].every(_hex16.hasMatch)) return false;
    final count = head.length + tail.length;
    return halves.length == 2 ? count < groups : count == groups;
  }

  static final _scheme = RegExp(r'^[A-Za-z][A-Za-z0-9+.-]*$');
  static final _uriChars = RegExp(r"^[A-Za-z0-9\-._~:/?#\[\]@!$&'()*+,;=%]*$");
  static final _pct = RegExp(r'%(?![0-9A-Fa-f]{2})');
  static final _regName = RegExp(r"^[A-Za-z0-9\-._~!$&'()*+,;=%]*$");

  /// RFC 3986 `URI` (absolute, fragment allowed).
  static bool _isUri(String value) {
    if (!_uriChars.hasMatch(value) || _pct.hasMatch(value)) return false;
    final colon = value.indexOf(':');
    if (colon <= 0 || !_scheme.hasMatch(value.substring(0, colon))) return false;
    var rest = value.substring(colon + 1);
    final hash = rest.indexOf('#');
    final fragment = hash >= 0 ? rest.substring(hash + 1) : '';
    if (hash >= 0) rest = rest.substring(0, hash);
    if (fragment.contains('#') || fragment.contains('[') || fragment.contains(']')) return false;
    if (rest.startsWith('//')) {
      final authorityEnd = rest.indexOf(RegExp(r'[/?]'), 2);
      final authority = authorityEnd < 0 ? rest.substring(2) : rest.substring(2, authorityEnd);
      rest = authorityEnd < 0 ? '' : rest.substring(authorityEnd);
      if (!_isAuthority(authority)) return false;
    }
    return !rest.contains('[') && !rest.contains(']');
  }

  static bool _isAuthority(String authority) {
    var hostPort = authority;
    final at = authority.lastIndexOf('@');
    if (at >= 0) {
      final userinfo = authority.substring(0, at);
      if (userinfo.contains('[') || userinfo.contains(']') || userinfo.contains('@')) return false;
      hostPort = authority.substring(at + 1);
    }
    String host;
    String? port;
    if (hostPort.startsWith('[')) {
      final close = hostPort.indexOf(']');
      if (close < 0) return false;
      host = hostPort.substring(1, close);
      final after = hostPort.substring(close + 1);
      if (after.isNotEmpty) {
        if (!after.startsWith(':')) return false;
        port = after.substring(1);
      }
      final ipvFuture = RegExp(r"^[vV][0-9A-Fa-f]+\.[A-Za-z0-9\-._~!$&'()*+,;=:]+$");
      if (!_isIPv6(host) && !ipvFuture.hasMatch(host)) return false;
    } else {
      final c = hostPort.lastIndexOf(':');
      host = c >= 0 ? hostPort.substring(0, c) : hostPort;
      if (c >= 0) port = hostPort.substring(c + 1);
      if (!_regName.hasMatch(host)) return false;
    }
    return port == null || RegExp(r'^[0-9]*$').hasMatch(port);
  }
}

class _Located {
  _Located(this.node, this.base);
  final Object? node;
  final Uri base;
}

/// Where evaluation is: the current base URI, the dynamic scope (outermost
/// first), and the instance / keyword locations.
class _Ctx {
  _Ctx(this.base, this.dynamicScope, this.ipath, this.kpath, this.depth);
  final Uri base;
  final List<Uri> dynamicScope;
  final String ipath;
  final String kpath;
  final int depth;

  _Ctx at(String keyword) => _Ctx(base, dynamicScope, ipath, '$kpath/$keyword', depth + 1);
  _Ctx item(String key) => _Ctx(base, dynamicScope, '$ipath/${_escape(key)}', kpath, depth);

  _Ctx withBase(Uri b) => _Ctx(
        b,
        dynamicScope.contains(b) ? dynamicScope : [...dynamicScope, b],
        ipath,
        kpath,
        depth,
      );

  _Ctx into(String keyword, Uri targetBase) => _Ctx(
        targetBase,
        dynamicScope.contains(targetBase) ? dynamicScope : [...dynamicScope, targetBase],
        ipath,
        '$kpath/$keyword',
        depth + 1,
      );
}

/// What a successful evaluation covered, for `unevaluated*`.
class _Annotations {
  _Annotations.valid() : ok = true;
  _Annotations.invalid() : ok = false;
  final bool ok;
  final Set<String> props = {};
  final Set<int> items = {};
  bool allItems = false;

  void merge(_Annotations other) {
    if (!other.ok) return;
    props.addAll(other.props);
    items.addAll(other.items);
    allItems = allItems || other.allItems;
  }
}

String _escape(String token) => token.replaceAll('~', '~0').replaceAll('/', '~1');

String _stripEmptyFragment(String uri) => uri.endsWith('#') ? uri.substring(0, uri.length - 1) : uri;

Uri _withoutFragment(Uri uri) => uri.hasFragment ? uri.removeFragment() : uri;
